<script>
$(function () {
    function wire($row){$row.find('.js-promotion-item').each(function(){var $el=$(this);$el.select2({theme:'bootstrap-5',width:'100%',allowClear:true,placeholder:'ค้นหาสินค้า',ajax:{url:$el.data('url'),dataType:'json',delay:250,data:function(p){return {q:p.term||''};},processResults:function(data){return data;}}}).on('select2:select',function(event){var item=event.params.data,$line=$(this).closest('.promotion-line');$line.find('.js-promotion-uom').text(item.uom_text||'ไม่พบหน่วย Stock').removeClass('text-secondary');$line.find('[name$="[uom_id]"]').val(item.uom_id||'');});});}
    function toggleScope(){var isDocument=$('#promotion-scope').val()==='DOCUMENT';$('#document-discount-card').toggle(isDocument).find(':input').prop('disabled',!isDocument);$('#line-rules-card').toggle(!isDocument).find(':input').prop('disabled',isDocument);}
    $('.promotion-line').each(function(){wire($(this));});
    $('.js-promotion-group').select2({theme:'bootstrap-5',width:'100%',allowClear:true,placeholder:'ทุกกลุ่ม',ajax:{url:$('.js-promotion-group').data('url'),dataType:'json',delay:250,data:function(p){return {q:p.term||''};},processResults:function(data){return data;}}});
    $('#promotion-scope').on('change',toggleScope);toggleScope();
    $('#add-promotion-line').on('click',function(){var index=$('#promotion-lines .promotion-line').length,row=$($('#promotion-line-template').html().replaceAll('__INDEX__',index));$('#promotion-lines').append(row);wire(row);});
    $(document).on('click','.js-remove-promotion-line',function(){if($('#promotion-lines .promotion-line').length>1)$(this).closest('.promotion-line').remove();});
    window.erpAjaxForm({form:'#promotion-form',redirect:{{ $promotion->exists ? 'false' : 'true' }} });
});
</script>
